// <static:cpp-logic>
/// A single tool call recorded inside an intermediate step.
struct ToolCallExample {
  std::string call_id;
  std::string tool_name;
  std::string stringified_input;
  std::string stringified_output;
};

/// One intermediate step within a few-shot example, containing the tool
/// calls made at that step.
struct IntermediateStepExample {
  /// Tool calls made in parallel at this step.
  std::vector<ToolCallExample> tool_calls;
};
/// A single few-shot example consisting of a user message, optional intermediate
/// tool-call steps, and the expected response.
struct FewShotExample {
  std::string user_message;
  std::vector<IntermediateStepExample> intermediate_steps;
  std::string response;
};

struct Tool {
  std::string name;
  std::string description;
  JsonNode input_json_schema;
};

/// A fully resolved prompt ready to be sent to an LLM.
struct Prompt {
  /// Metadata for this prompt.
  Meta meta{};
  std::string system_message;
  std::string user_message;

  /// Few-shot examples.
  std::vector<FewShotExample> examples;

  /// The tools which can be called by the LLM, keyed by tool name.
  std::map<std::string, Tool> tools;

  /// The expected format of the model output.
  OutputFormat output_format{};
  /// Set if 'output_format' is 'kJson'.
  std::optional<JsonNode> output_json_schema;

  /// Uniquely identifies the prompt template.
  std::string template_id;
};

struct ToolCall {
  std::string call_id;
  std::string tool_name;
  std::string stringified_input;
};

struct ToolCallResponse {
  std::string call_id;

  /// The JSON-stringified output of the tool call:
  /// - On success, contains the JSON-serialized return value of the tool.
  /// - On failure, contains a JSON object with a single "error" key containing
  ///   the error message (e.g. `{"error": "..."}`).
  ///
  /// Integration guide:
  /// - **OpenAI / Gemini SDKs**: Forward `stringified_output` directly as the
  ///   tool result content and ignore the `error` field.
  /// - **Anthropic SDK**: Check if `error` is set. If set, mark `is_error = true`
  ///   in the tool result block and pass the error message to `content`. Otherwise,
  ///   pass `stringified_output` to `content`.

  std::string stringified_output;
  /// The error message if the tool call failed, or `std::nullopt` on success.
  ///
  /// Set when tool argument parsing fails, when the tool itself returns an error,
  /// or when the requested tool is not found.
  std::optional<std::string> error;
};

/// Type-erased interface for executing LLM-requested tool calls.
///
/// Use `MakeToolExecutor` to construct an instance bound to a specific prompt template.
class ToolExecutor {
 public:
  virtual ~ToolExecutor() = default;

  /// Executes a single tool call requested by an LLM.
  ///
  /// \param tool_call The incoming tool invocation with call ID, tool name, and JSON input.
  /// \return The serialized response (or error message) ready to return to the LLM API.
  virtual ToolCallResponse Execute(const ToolCall& tool_call) = 0;
};

namespace internal {
template <typename Tuple, typename F>
constexpr void for_each_type(F&& f) {
  // Immediately invoke a template lambda to generate the index sequence
  [&]<std::size_t... Is>(std::index_sequence<Is...>) {
    // Fold expression passes std::type_identity<T> for each type
    (f(std::type_identity<std::tuple_element_t<Is, Tuple>>{}), ...);
  }(std::make_index_sequence<std::tuple_size_v<Tuple>>{});
}

template <typename Template, typename TypedHandlerPtr>
class ToolExecutorImpl : public ToolExecutor {
 public:
  ToolExecutorImpl(TypedHandlerPtr typed_handler) : typed_handler_(std::move(typed_handler)) {
    assert(typed_handler != nullptr);
  }

  ToolCallResponse Execute(const ToolCall& tool_call) override {
    using tools_type = typename Template::tools_type;
    std::optional<Result<ToolCallResponse>> result;
    internal::for_each_type<tools_type>([this, &tool_call, &result]<typename tool_type>(
                                            std::type_identity<tool_type>) {
      using input_type = typename tool_type::input_type;
      using output_type = typename tool_type::output_type;
      if (tool_type::kToolName != tool_call.tool_name) return;
      auto input_result = ParseJson<input_type>(tool_call.stringified_input);
      if (!input_result.ok()) {
        result = Error(std::format("Failed to parse tool input: {}", input_result.error().message));
        return;
      }
      constexpr tool_type tool{};
      Result<output_type> output_result = (*typed_handler_)(tool, *input_result);
      if (!output_result.ok()) {
        result = std::move(output_result).error();
        return;
      }
      result = ToolCallResponse{
          .call_id = tool_call.call_id,
          .stringified_output = ToJson(*output_result),
          .error = std::nullopt,
      };
    });
    if (!result.has_value()) {
      result = Error(std::format("Tool not found: {}", tool_call.tool_name));
    }
    if (!result->ok()) {
      const std::string& error_msg = result->error().message;
      const JsonNode error_node = JsonNode::Object{{"error", error_msg}};
      return ToolCallResponse{
          .call_id = tool_call.call_id,
          .stringified_output = error_node.ToJson(),
          .error = error_msg,
      };
    }
    return **result;
  }

 private:
  const TypedHandlerPtr typed_handler_;
};
}  // namespace internal

/// Creates a `ToolExecutor` bound to a specific prompt template and typed tool handler.
///
/// The handler object must implement an overloaded `operator()` for each tool
/// declared in the template's `tools_type`:
///
/// ```cpp
/// struct MyToolHandler {
///   typeprompt::Result<schema::web_search::Output> operator()(
///       tools::WebSearch,
///       const schema::web_search::Input& input) {
///     // Implementation...
///     return schema::web_search::Output{ ... };
///   }
/// };
///
/// MyToolHandler handler;
/// auto executor = MakeToolExecutor<templates::ResearchQuestion>(&handler);
/// ```
///
/// \tparam Template The template struct generated in the `templates` namespace (e.g.
/// `templates::ResearchQuestion`).
/// \tparam TypedHandlerPtr Pointer or smart pointer (e.g., `MyHandler*`,
/// `std::shared_ptr<MyHandler>`) to an instance implementing the tool call operator overloads.
/// \param typed_handler Pointer or smart pointer to the typed tool handler. Must not be null.
/// \return A std::unique_ptr<ToolExecutor> executing tool calls for the template.
template <typename Template, typename TypedHandlerPtr>
std::unique_ptr<ToolExecutor> MakeToolExecutor(TypedHandlerPtr typed_handler) {
  return std::make_unique<internal::ToolExecutorImpl<Template, TypedHandlerPtr>>(
      std::move(typed_handler));
}

namespace internal {
class Renderer {
 public:
  static Prompt Render(std::string_view template_id, const JsonNode& input,
                       const spec::Templates& spec) {
    return RenderImpl(template_id, input, spec);
  }

  static Prompt RenderImpl(std::string_view template_id, const JsonNode& input,
                           const spec::Templates& spec) {
    auto tmpl_it = spec.templates.find(std::string(template_id));
    if (tmpl_it == spec.templates.end()) {
      throw std::invalid_argument(std::format("Template not found: {}", template_id));
    }
    const spec::Template& template_val = tmpl_it->second;

    const auto& snippets = template_val.snippets;
    const auto& contents = template_val.contents;

    std::optional<JsonNode> meta_element;
    std::string system_message;
    std::string user_message;
    std::vector<FewShotExample> examples;

    switch (contents.kind()) {
      case spec::TemplateContents::kind::kNoVariants: {
        const auto& content = contents.as_kind_no_variants().content;
        meta_element = content.meta;
        const auto& system_body =
            content.system.has_value() ? *content.system : std::vector<spec::BodyPiece>{};
        system_message = RenderBody(system_body, input, snippets);
        const auto& user_body =
            content.user.has_value() ? *content.user : std::vector<spec::BodyPiece>{};
        user_message = RenderBody(user_body, input, snippets);
        examples = RenderExamples(content.examples, user_body, template_val);
        break;
      }
      case spec::TemplateContents::kind::kVariants: {
        if (input.type() != JsonNode::Type::kObject) {
          throw std::invalid_argument("Input for template with variants must be an object");
        }
        std::string variant_str;
        bool found_variant = false;
        for (const auto& [k, v] : input.as_object()) {
          if (k == "variant") {
            switch (v.type()) {
              case JsonNode::Type::kString:
                variant_str = v.as_string();
                found_variant = true;
                break;
              case JsonNode::Type::kBool:
                variant_str = v.as_bool() ? "true" : "false";
                found_variant = true;
                break;
              case JsonNode::Type::kNumber:
                variant_str = NumberFormatter::Format(v.as_number());
                found_variant = true;
                break;
              default:
                break;
            }
            break;
          }
        }
        if (!found_variant) {
          throw std::invalid_argument("Missing 'variant' field in input");
        }
        const auto& variants_obj = contents.as_kind_variants();
        auto var_it = variants_obj.variants.find(variant_str);
        if (var_it == variants_obj.variants.end()) {
          throw std::invalid_argument("Unknown variant: " + variant_str);
        }
        const auto& variant_content = var_it->second;
        const auto& default_content = variants_obj.default_content;

        meta_element =
            variant_content.meta.has_value() ? variant_content.meta : default_content.meta;

        const auto& system_body =
            variant_content.system.has_value()
                ? *variant_content.system
                : (default_content.system.has_value() ? *default_content.system
                                                      : std::vector<spec::BodyPiece>{});
        const auto& user_body =
            variant_content.user.has_value()
                ? *variant_content.user
                : (default_content.user.has_value() ? *default_content.user
                                                    : std::vector<spec::BodyPiece>{});
        system_message = RenderBody(system_body, input, snippets);
        user_message = RenderBody(user_body, input, snippets);

        const auto& raw_examples = variant_content.examples.has_value() ? variant_content.examples
                                                                        : default_content.examples;
        examples = RenderExamples(raw_examples, user_body, template_val);
        break;
      }
    }

    Meta meta{};
    if (meta_element.has_value() && meta_element->type() != JsonNode::Type::kNull) {
      auto res = Parse<Meta>(*meta_element);
      if (res.ok()) {
        meta = std::move(*res);
      }
    }

    std::map<std::string, Tool> tools;
    for (const auto& template_tool : template_val.tools_) {
      auto tool_it = spec.tools_.find(template_tool.id);
      if (tool_it == spec.tools_.end()) {
        throw std::invalid_argument("Tool spec not found: " + template_tool.id);
      }
      Tool tool;
      tool.name = template_tool.name;
      tool.description = tool_it->second.description;
      tool.input_json_schema = tool_it->second.input_json_schema;
      tools[template_tool.name] = std::move(tool);
    }

    OutputFormat output_format = (template_val.output_format == spec::OutputFormat_::kJson)
                                     ? OutputFormat::kJson
                                     : OutputFormat::kText;
    std::optional<JsonNode> output_json_schema;
    if (output_format == OutputFormat::kJson) {
      output_json_schema = template_val.output_json_schema;
    }

    return Prompt{
        .meta = std::move(meta),
        .system_message = std::move(system_message),
        .user_message = std::move(user_message),
        .examples = std::move(examples),
        .tools = std::move(tools),
        .output_format = output_format,
        .output_json_schema = std::move(output_json_schema),
        .template_id = std::string(template_id),
    };
  }

  template <typename Template>
  static Result<typename Template::output_type> ParseResponseImpl(std::string_view response) {
    if constexpr (Template::kOutputFormat == OutputFormat::kJson) {
      std::string_view cleaned = Trim(response);
      if (cleaned.starts_with("```")) {
        if (cleaned.starts_with("```json")) {
          cleaned.remove_prefix(7);
        } else {
          cleaned.remove_prefix(3);
        }
        if (cleaned.ends_with("```")) {
          cleaned.remove_suffix(3);
        }
      }
      auto result = ParseJson<typename Template::output_type>(cleaned);
      if (!result.ok()) {
        return Error{
            std::format("Template '{}': {}", Template::kTemplateId, result.error().message)};
      }
      return result;
    } else {
      return ParseJson<typename Template::output_type>(response);
    }
  }

 private:
  static std::string_view Trim(std::string_view s) {
    while (!s.empty() && std::isspace(static_cast<unsigned char>(s.front()))) {
      s.remove_prefix(1);
    }
    while (!s.empty() && std::isspace(static_cast<unsigned char>(s.back()))) {
      s.remove_suffix(1);
    }
    return s;
  }

  static JsonNode Evaluate(const spec::Expression& expression, const JsonNode& val) {
    switch (expression.kind()) {
      case spec::Expression::kind::kInput:
        return val;
      case spec::Expression::kind::kProperty: {
        const auto& prop = expression.as_kind_property();
        JsonNode left_val = Evaluate(prop.left, val);
        if (left_val.type() == JsonNode::Type::kObject) {
          for (const auto& [k, v] : left_val.as_object()) {
            if (k == prop.property) {
              return v;
            }
          }
        }
        return std::nullopt;
      }
    }
    return std::nullopt;
  }

  static std::string Indent(std::string_view text, std::string_view spaces) {
    if (spaces.empty()) return std::string(text);
    std::string result;
    result.reserve(text.size() + spaces.size() * 4);
    for (size_t i = 0; i < text.size(); ++i) {
      result += text[i];
      if (text[i] == '\n') {
        result += spaces;
      }
    }
    return result;
  }

  static std::string FormatTable(const JsonNode& v, spec::InsertFormat fmt) {
    if (v.type() != JsonNode::Type::kArray) {
      return "";
    }
    const auto& list = v.as_array();
    if (list.empty()) {
      return "";
    }
    if (list[0].type() != JsonNode::Type::kObject) {
      return "";
    }
    const auto& first_row = list[0].as_object();
    std::vector<std::string> headers;
    for (const auto& [key, _] : first_row) {
      headers.push_back(key);
    }
    const char* separator = (fmt == spec::InsertFormat::kCsv) ? "," : "\t";
    std::string result;
    // First line: headers
    for (size_t i = 0; i < headers.size(); ++i) {
      if (i > 0) result += separator;
      result += headers[i];
    }
    // Data lines
    for (const auto& item : list) {
      if (item.type() == JsonNode::Type::kObject) {
        const auto& obj = item.as_object();
        result += "\n";
        for (size_t i = 0; i < headers.size(); ++i) {
          if (i > 0) result += separator;
          const std::string& key = headers[i];
          std::string str;
          for (const auto& [k, val] : obj) {
            if (k == key) {
              switch (val.type()) {
                case JsonNode::Type::kNull:
                  str = "";
                  break;
                case JsonNode::Type::kBool:
                  str = val.as_bool() ? "true" : "false";
                  break;
                case JsonNode::Type::kNumber:
                  str = NumberFormatter::Format(val.as_number());
                  break;
                case JsonNode::Type::kString:
                  str = val.as_string();
                  break;
                default:
                  str = val.ToJson();
                  break;
              }
              break;
            }
          }
          if (fmt == spec::InsertFormat::kCsv) {
            if (str.find('"') != std::string::npos || str.find(',') != std::string::npos ||
                str.find('\n') != std::string::npos || str.find('\r') != std::string::npos) {
              std::string escaped = "\"";
              for (char c : str) {
                if (c == '"') {
                  escaped += "\"\"";
                } else {
                  escaped += c;
                }
              }
              escaped += '"';
              result += escaped;
            } else {
              result += str;
            }
          } else {
            // TSV
            std::string escaped;
            for (char c : str) {
              if (c == '\\') {
                escaped += "\\\\";
              } else if (c == '\t') {
                escaped += "\\t";
              } else if (c == '\n') {
                escaped += "\\n";
              } else if (c == '\r') {
                escaped += "\\r";
              } else {
                escaped += c;
              }
            }
            result += escaped;
          }
        }
      }
    }
    return result;
  }

  static std::string FormatValue(const JsonNode& v, spec::InsertFormat fmt) {
    switch (fmt) {
      case spec::InsertFormat::kText: {
        switch (v.type()) {
          case JsonNode::Type::kNull:
            return "";
          case JsonNode::Type::kBool:
            return v.as_bool() ? "true" : "false";
          case JsonNode::Type::kNumber:
            return NumberFormatter::Format(v.as_number());
          case JsonNode::Type::kString:
            return v.as_string();
          default:
            return v.ToJson();
        }
      }
      case spec::InsertFormat::kJson:
        return v.ToPrettyJson();
      case spec::InsertFormat::kYaml:
        return v.ToYaml();
      case spec::InsertFormat::kToon:
        return v.ToToon();
      case spec::InsertFormat::kCsv:
      case spec::InsertFormat::kTsv:
        return FormatTable(v, fmt);
    }
    return "";
  }

  static std::string RenderSnippet(const spec::Snippet& snippet, const JsonNode& inp,
                                   const std::map<std::string, spec::Snippet>& snippets) {
    switch (snippet.kind()) {
      case spec::Snippet::kind::kSnippet: {
        return RenderBody(snippet.as_kind_snippet().body, inp, snippets);
      }
      case spec::Snippet::kind::kSnippetIf: {
        const auto& snip_if = snippet.as_kind_snippet_if();
        JsonNode eval_result = Evaluate(snip_if.expression, inp);
        bool condition = false;
        switch (snip_if.is) {
          case spec::Snippet_KindSnippetIf_Is::kNotEmpty: {
            switch (eval_result.type()) {
              case JsonNode::Type::kArray:
                condition = !eval_result.as_array().empty();
                break;
              case JsonNode::Type::kObject:
                condition = !eval_result.as_object().empty();
                break;
              case JsonNode::Type::kString:
                condition = !eval_result.as_string().empty();
                break;
              case JsonNode::Type::kNull:
                condition = false;
                break;
              default:
                condition = true;
                break;
            }
            break;
          }
          case spec::Snippet_KindSnippetIf_Is::kNotNull: {
            condition = (eval_result.type() != JsonNode::Type::kNull);
            break;
          }
          case spec::Snippet_KindSnippetIf_Is::kTrue: {
            switch (eval_result.type()) {
              case JsonNode::Type::kBool:
                condition = eval_result.as_bool();
                break;
              case JsonNode::Type::kString:
                condition = !eval_result.as_string().empty();
                break;
              case JsonNode::Type::kNumber:
                condition = (static_cast<int64_t>(eval_result.as_number()) != 0);
                break;
              case JsonNode::Type::kNull:
                condition = false;
                break;
              default:
                condition = true;
                break;
            }
            break;
          }
        }
        return RenderBody(condition ? snip_if.then : snip_if.else_, inp, snippets);
      }
      case spec::Snippet::kind::kSnippetSwitch: {
        const auto& snip_switch = snippet.as_kind_snippet_switch();
        JsonNode switch_val = Evaluate(snip_switch.expression, inp);
        std::string switch_key;
        switch (switch_val.type()) {
          case JsonNode::Type::kBool:
            switch_key = switch_val.as_bool() ? "true" : "false";
            break;
          case JsonNode::Type::kString:
            switch_key = switch_val.as_string();
            break;
          case JsonNode::Type::kNumber:
            switch_key = NumberFormatter::Format(switch_val.as_number());
            break;
          case JsonNode::Type::kNull:
            switch_key = "";
            break;
          default:
            switch_key = switch_val.ToJson();
            break;
        }
        auto it = snip_switch.branches.find(switch_key);
        if (it == snip_switch.branches.end()) {
          throw std::invalid_argument("Branch not found: " + switch_key);
        }
        return RenderBody(it->second, inp, snippets);
      }
    }
    return "";
  }

  static std::string RenderBody(const std::vector<spec::BodyPiece>& body, const JsonNode& inp,
                                const std::map<std::string, spec::Snippet>& snippets) {
    if (body.empty()) {
      return "";
    }
    std::string sb;
    for (const auto& piece : body) {
      switch (piece.kind()) {
        case spec::BodyPiece::kind::kText: {
          sb += piece.as_kind_text().text;
          break;
        }
        case spec::BodyPiece::kind::kInsertVal: {
          const auto& insert_val = piece.as_kind_insert_val();
          JsonNode val = Evaluate(insert_val.val, inp);
          std::string formatted = FormatValue(val, insert_val.format);
          sb += Indent(formatted, insert_val.indent);
          break;
        }
        case spec::BodyPiece::kind::kInsertSnippet: {
          const auto& insert_snip = piece.as_kind_insert_snippet();
          auto it = snippets.find(insert_snip.snippet);
          if (it == snippets.end()) {
            throw std::invalid_argument("Snippet not found: " + insert_snip.snippet);
          }
          std::string rendered_snippet = RenderSnippet(it->second, inp, snippets);
          sb += Indent(rendered_snippet, insert_snip.indent);
          break;
        }
      }
    }
    return sb;
  }

  static std::vector<FewShotExample> RenderExamples(
      const std::optional<std::vector<spec::FewShotExample>>& examples,
      const std::vector<spec::BodyPiece>& user_body, const spec::Template& tmpl) {
    if (!examples.has_value() || examples->empty()) {
      return {};
    }
    std::vector<FewShotExample> result;
    for (const auto& ex : *examples) {
      std::string user_message = RenderBody(user_body, ex.input, tmpl.snippets);

      std::vector<IntermediateStepExample> intermediate_steps;
      for (const auto& step : ex.intermediate_steps) {
        std::vector<ToolCallExample> tool_calls;
        for (const auto& tc : step.tool_calls) {
          tool_calls.push_back(ToolCallExample{
              .call_id = tc.call_id,
              .tool_name = tc.tool_name,
              .stringified_input = tc.input.ToJson(),
              .stringified_output = tc.output.ToJson(),
          });
        }
        intermediate_steps.push_back(IntermediateStepExample{
            .tool_calls = std::move(tool_calls),
        });
      }

      spec::InsertFormat output_format = (tmpl.output_format == spec::OutputFormat_::kJson)
                                             ? spec::InsertFormat::kJson
                                             : spec::InsertFormat::kText;
      std::string response = FormatValue(ex.output, output_format);

      result.push_back(FewShotExample{
          .user_message = std::move(user_message),
          .intermediate_steps = std::move(intermediate_steps),
          .response = std::move(response),
      });
    }
    return result;
  }
};

class TemplatesSpecAccessor;
}  // namespace internal

class TemplateOverrider;

/// Encapsulates compiled prompt templates data.
class Templates {
 public:
  Templates(const Templates&) = delete;
  Templates& operator=(const Templates&) = delete;
  Templates(Templates&&) = default;
  Templates& operator=(Templates&&) = default;

  static const Templates& getDefault() {
    static const Templates* kDefault = new Templates(internal::TemplatesData::get());
    return *kDefault;
  }

 private:
  friend class TemplateOverrider;
  friend class internal::TemplatesSpecAccessor;

  explicit Templates(internal::spec::Templates spec) : spec_(std::move(spec)) {}

  const internal::spec::Templates& spec() const { return spec_; }

  internal::spec::Templates spec_;
};

namespace internal {
class TemplatesSpecAccessor {
 public:
  static const spec::Templates get(const Templates& input) { return input.spec_; }
};

// Check if T has a member type named 'whole'
template <typename T>
concept has_whole = requires { typename T::whole; };

template <typename T>
struct whole_or_const_ref {
  using type = const T&;
};
template <has_whole T>
struct whole_or_const_ref<T> {
  using type = typename T::whole;
};

// If Template::input_type (T) is a generated struct, resolves to 'T::whole'.
// Otherwise, resolves to 'const T&'.
template <typename Template>
using input_type = typename whole_or_const_ref<typename Template::input_type>::type;
}  // namespace internal

/// Use this with external frameworks that support template override injection
/// for experimentation or A/B testing.
class TemplateOverrider {
 public:
  /// Returns the compiled prompt templates serialized as a JsonNode.
  static JsonNode templatesData() {
    using internal::spec::ToJsonNode;
    return ToJsonNode(internal::TemplatesSpecAccessor::get(Templates::getDefault()));
  }

  /// Applies JSON overrides and returns an updated Templates instance, or an Error.
  static Result<Templates> applyOverrides(const JsonNode& overrides) {
    auto overrides_value = Parse<internal::spec::Templates>(overrides);
    if (!overrides_value.ok()) {
      return std::move(overrides_value).error();
    }

    internal::spec::Templates result =
        internal::TemplatesSpecAccessor::get(Templates::getDefault());

    if (overrides_value->signature != result.signature) {
      return Error{"Signature mismatch"};
    }

    for (auto& [tpl_id, tpl] : overrides_value->templates) {
      result.templates[tpl_id] = std::move(tpl);
    }
    for (auto& [tool_id, tool] : overrides_value->tools_) {
      result.tools_[tool_id] = std::move(tool);
    }
    for (auto& [path, source_file] : overrides_value->source_files) {
      result.source_files[path] = std::move(source_file);
    }

    return Templates(std::move(result));
  }
};

/// Renders a prompt template with the provided input.
///
/// \tparam Template One of the template structs generated in the 'templates' namespace (e.g.,
/// 'templates::MyTemplate').
/// \param input The input arguments matching the template's input schema.
/// \param templates Optional template definitions, useful when injecting prompt overrides from an
/// external experimentation or A/B testing framework. Defaults to the compiled templates.
/// \return A fully resolved Prompt ready to be sent to an LLM.
template <typename Template, typename Input = internal::input_type<Template>>
Prompt Render(Input input, const Templates& templates = Templates::getDefault()) {
  if constexpr (internal::has_whole<typename Template::input_type> &&
                std::is_same_v<std::decay_t<Input>, typename Template::input_type::whole>) {
    const typename Template::input_type input_val = std::move(input);
    return internal::Renderer::RenderImpl(Template::kTemplateId, ToJsonNode(input_val),
                                          internal::TemplatesSpecAccessor::get(templates));
  } else {
    return internal::Renderer::RenderImpl(Template::kTemplateId, ToJsonNode(input),
                                          internal::TemplatesSpecAccessor::get(templates));
  }
}

/// Parses and validates an LLM response against the template's output schema.
///
/// \tparam Template One of the template structs generated in the 'templates' namespace (e.g.,
/// 'templates::MyTemplate').
/// \param response The raw string response returned by the LLM.
/// \return A Result containing the structured output or an Error.
template <typename Template>
Result<typename Template::output_type> ParseResponse(std::string_view response) {
  return internal::Renderer::ParseResponseImpl<Template>(response);
}
